import{_ as e,o,c as n,ag as r}from"./chunks/framework.2cFhd8Ux.js";const m=JSON.parse('{"title":"The Final Defense","description":"","frontmatter":{"source":"project/final-defense.md"},"headers":[],"relativePath":"project/final-defense.md","filePath":"project/final-defense.md"}'),a={name:"project/final-defense.md"};function i(s,t,d,h,l,u){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="the-final-defense" tabindex="-1">The Final Defense <a class="header-anchor" href="#the-final-defense" aria-label="Permalink to &quot;The Final Defense&quot;">​</a></h1><blockquote><p>The course&#39;s final event, in finals week: each team shows its contribution working in the class codebase and reruns one of its checks live, then each member answers questions about their own work with the AI off. Behavior you can demonstrate, checks anyone can reproduce, and limitations you name yourself.</p></blockquote><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>Finals week (week 16), in the course&#39;s scheduled <strong>2-hour final exam slot</strong> (University Regulation H-1-b: final sessions follow the approved final exam schedule): [day, time and room, posted on Canvas]</td></tr><tr><td><strong>Who</strong></td><td>Every team, every member. CS [5xxx] students defend with their team; their study talk was in week 15</td></tr><tr><td><strong>Format</strong></td><td>Per team, about 18 minutes: a 6-minute demo with a live reproducible check, a team question, then about 2–3 minutes of individual questions per member</td></tr><tr><td><strong>Points</strong></td><td>30 of the Final&#39;s 65: the team demo 10 (Team), your individual questions 20 (Individual) (<a href="#rubric">rubric</a>)</td></tr><tr><td><strong>AI use</strong></td><td>🔴 AI off for the individual questions. The demo shows your team&#39;s work, built with whatever the course allowed</td></tr><tr><td><strong>Required</strong></td><td>Taking the final defense is required for a C or higher (<a href="./../assessment/#letter-grades">letter grades</a>)</td></tr></tbody></table><h2 id="the-principle" tabindex="-1">The principle <a class="header-anchor" href="#the-principle" aria-label="Permalink to &quot;The principle&quot;">​</a></h2><p>The defense, like the final report, is graded on the rule UT Austin&#39;s CS 378 sets for its final projects:</p><blockquote><p>&quot;Feature count, repository size, token spend, prompt volume, and visual polish do not substitute for demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations.&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">UT Austin CS 378</a>)</p></blockquote><p>So a small contribution that works, with a check you can rerun in front of the room and a limitation you name before anyone asks, scores better than a large one you can&#39;t verify or explain. The individual questions exist because a team demo can&#39;t show who understands what: students who build with agents can finish faster while understanding less of their own code (<a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">Balepur et al.</a>).</p><h2 id="before-the-slot" tabindex="-1">Before the slot <a class="header-anchor" href="#before-the-slot" aria-label="Permalink to &quot;Before the slot&quot;">​</a></h2><ul><li>☐ <strong>Freeze <code>main</code>.</strong> Merge everything you want graded before the slot starts. Staff tag your fork&#39;s <code>main</code> as <code>final</code> at the start of the slot; you demo that commit, and staff grade it.</li><li>☐ <strong>Write a demo script</strong> (one page, for your team): what you&#39;ll show, in what order, which check you&#39;ll rerun and how long it takes, and the one limitation you&#39;ll state. Have a fallback for each step: a recorded CI run if the live check is slow, screenshots if the network fails.</li><li>☐ <strong>Prepare the environment.</strong> A Codespace on the tagged commit, already built, with the check&#39;s command ready. Open it 30 minutes before the slot; free machines can be slow to start.</li><li>☐ <strong>Each member:</strong> reread your own PRs, your <code>course/AI_LOG.md</code> entries and your team&#39;s week 14 report draft. The individual questions come from them.</li><li>☐ <strong>Rehearse</strong> in the week 15 Lab&#39;s dry run, and time it.</li></ul><h2 id="in-the-slot" tabindex="-1">In the slot <a class="header-anchor" href="#in-the-slot" aria-label="Permalink to &quot;In the slot&quot;">​</a></h2><p>The order of teams is posted on Canvas a week before. Everyone stays for the whole slot: seeing how the other teams verified their work is part of the course.</p><table tabindex="0"><thead><tr><th>Time</th><th>What</th></tr></thead><tbody><tr><td>5 min</td><td>Opening: the order, the rules, AI tools closed</td></tr><tr><td>About 18 min per team</td><td><strong>Setup</strong> (1 min) · <strong>Demo</strong> (6 min) · <strong>Team question</strong> (1–2 min) · <strong>Individual questions</strong> (about 2–3 min per member) · changeover (1 min)</td></tr><tr><td>5 min</td><td>Close</td></tr></tbody></table><h3 id="the-demo-6-minutes" tabindex="-1">The demo (6 minutes) <a class="header-anchor" href="#the-demo-6-minutes" aria-label="Permalink to &quot;The demo (6 minutes)&quot;">​</a></h3><ol><li><strong>What you contributed and why</strong>, in one sentence each.</li><li><strong>Demonstrated behavior:</strong> the contribution working in the class codebase, on the <code>final</code> tag, on the main scenario from your spec and one edge case.</li><li><strong>A reproducible check, rerun live:</strong> your test suite, the mutation run on a changed module, or your eval on recorded responses, with its result compared to the number in your report. If it takes more than a minute or two, start it at the beginning and show the result at the end.</li><li><strong>One honest limitation,</strong> stated without being asked: something that doesn&#39;t work, a number you don&#39;t fully trust, a risk you didn&#39;t close.</li></ol><h3 id="the-team-question-12-minutes" tabindex="-1">The team question (1–2 minutes) <a class="header-anchor" href="#the-team-question-12-minutes" aria-label="Permalink to &quot;The team question (1–2 minutes)&quot;">​</a></h3><p>One question to the whole team, usually about a decision in your report: &quot;Why this design and not the alternative you list?&quot; Any member may answer.</p><h3 id="individual-questions-about-23-minutes-each" tabindex="-1">Individual questions (about 2–3 minutes each) <a class="header-anchor" href="#individual-questions-about-23-minutes-each" aria-label="Permalink to &quot;Individual questions (about 2–3 minutes each)&quot;">​</a></h3><p>Each member answers alone, with the AI off. The examiner prepares questions from your PRs, your <code>AI_LOG.md</code> entries and the week 14 draft. Expect one or two of these:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Example</th></tr></thead><tbody><tr><td><strong>Explain your contribution</strong></td><td>&quot;Walk us through PR #[n]. What did the code do before, and what does it do now?&quot;</td></tr><tr><td><strong>Defend a decision</strong></td><td>&quot;What did you specify, what did you delegate to the agent, and how did you verify it? Would you delegate it again?&quot;</td></tr><tr><td><strong>Predict or modify</strong></td><td>&quot;If the upstream project changed this function&#39;s signature, what in your change would break, and which test would tell you?&quot; · &quot;Show me where you&#39;d add a check for [edge case].&quot;</td></tr><tr><td><strong>Account for AI use and limits</strong></td><td>&quot;Name something an agent got wrong in your part of the work. How did you find out?&quot;</td></tr></tbody></table><p>You may use the tagged repository on screen to answer. You may also ask for your questions to be taken privately at the end of the slot instead of in front of the class (<a href="#accommodations">accommodations</a>).</p><h2 id="rubric" tabindex="-1">Rubric <a class="header-anchor" href="#rubric" aria-label="Permalink to &quot;Rubric&quot;">​</a></h2><p><strong>Team demo (10 points, Team).</strong></p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Demonstrated behavior</strong></td><td><strong>4</strong> · The contribution works live on the <code>final</code> tag, on the main scenario and an edge case, as the report says</td><td><strong>3</strong> · Works on the main scenario; the edge case is shown from a test</td><td><strong>1</strong> · Works only partly, or only from screenshots without a reason</td><td><strong>0</strong> · Not shown</td></tr><tr><td><strong>Reproducible check</strong></td><td><strong>3</strong> · A check rerun live (or its CI run on the tagged commit opened live), and its result matches the report</td><td><strong>2</strong> · Rerun, with a small unexplained difference from the report</td><td><strong>1</strong> · Only described, not run</td><td><strong>0</strong> · None</td></tr><tr><td><strong>Honest limitations</strong></td><td><strong>3</strong> · At least one real limitation stated without being asked, with what it means for a user or maintainer</td><td><strong>2</strong> · A limitation stated when asked</td><td><strong>1</strong> · &quot;No limitations&quot;</td><td><strong>0</strong> · Claims contradicted by the demo itself</td></tr></tbody></table><p><strong>Individual questions (20 points, Individual, 🔴 AI off).</strong> Each criterion is scored 0–5 from what you say and show in your questions.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>5</th><th>3–4</th><th>1–2</th><th>0</th></tr></thead><tbody><tr><td><strong>Explain your contribution</strong></td><td>Accurate, in your own words, connected to the rest of the codebase, without hints</td><td>Accurate with a small gap or one hint (4), or with several hints (3)</td><td>Partly right, or reads the code aloud more than explains it</td><td>Can&#39;t explain it</td></tr><tr><td><strong>Defend a decision</strong></td><td>Says what you specified, delegated and verified, the alternative you rejected and the evidence for the choice</td><td>Gives reasons and evidence, with one part thin</td><td>Describes the decision but not why</td><td>No account</td></tr><tr><td><strong>Predict or modify</strong></td><td>Predicts correctly what would break and how you&#39;d know, or shows exactly where a change goes and how you&#39;d test it</td><td>Mostly right, with a hint</td><td>A plausible guess without reasoning</td><td>No attempt</td></tr><tr><td><strong>Account for AI use and limits</strong></td><td>A specific thing an agent got wrong, how you caught it, and what you changed; consistent with your <code>AI_LOG.md</code></td><td>A specific example, with less detail</td><td>Generic (&quot;sometimes it hallucinates&quot;)</td><td>Contradicts the record</td></tr></tbody></table><p>&quot;I don&#39;t know, but I&#39;d check the test for that path&quot; is a real answer, and earns credit where it belongs. Accents, grammar and nerves are never scored.</p><h2 id="accommodations" tabindex="-1">Accommodations <a class="header-anchor" href="#accommodations" aria-label="Permalink to &quot;Accommodations&quot;">​</a></h2><p>Follow the student&#39;s CDAR accommodation letter, agreed before the slot. These options are open to anyone who asks in advance:</p><ul><li><strong>Private questions:</strong> your individual questions at the end of the slot, with only the examiner, instead of in front of the class.</li><li><strong>Extra time</strong> for your individual questions, or a written-first version: the examiner gives you one question 10 minutes before your team&#39;s block.</li><li><strong>Typed answers</strong>, an interpreter or live captions, your own assistive technology.</li><li><strong>Presenting the demo:</strong> any member can drive the demo; nobody has to speak in it if that is a barrier, as long as they answer their individual questions in some form.</li></ul><h2 id="if-you-miss-the-defense" tabindex="-1">If you miss the defense <a class="header-anchor" href="#if-you-miss-the-defense" aria-label="Permalink to &quot;If you miss the defense&quot;">​</a></h2><ul><li><strong>Recognized absence</strong> (Regulation M-1: official university activities, your own illness, family illness or care, other compelling circumstances; Regulation M-3: religious observance): your team demos without you, and your individual questions are rescheduled before the grade deadline, in person or by video, with the same rubric.</li><li><strong>Other absences:</strong> your individual part scores 0, and because taking the defense is required for a C or higher, contact the instructor at once. An Incomplete is possible only under Regulation F.</li><li><strong>A team member who can&#39;t come</strong> doesn&#39;t change the team&#39;s demo score.</li></ul>',31)])])}const g=e(a,[["render",i]]);export{m as __pageData,g as default};
